// Standalone Stage-3B cross-side/dense DDG experiment. Not production.
#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <functional>
#include <numeric>
#include <queue>
#include <sys/resource.h>
#include <tuple>
#include <utility>
#include <vector>
using u64=uint64_t; static constexpr u64 INF=UINT64_MAX/4;
struct Edge{int v,w;}; struct Graph{int V,n;std::vector<std::vector<Edge>> a;};
static Graph load_graph(const char*p){FILE*f=fopen(p,"r");int V,E,fl;if(!f||fscanf(f,"%d%d%d",&V,&E,&fl)!=3||(fl&2))abort();int n=std::sqrt(V);if(n*n!=V)abort();Graph g{V,n,std::vector<std::vector<Edge>>(V)};for(int i=0,u,v,w;i<E;i++){if(fscanf(f,"%d%d%d",&u,&v,&w)!=3)abort();g.a[u].push_back({v,w});g.a[v].push_back({u,w});}fclose(f);return g;}
struct Query{int s,t;}; static std::vector<Query> load_queries(const char*p,int limit){FILE*f=fopen(p,"r");int q;if(!f||fscanf(f,"%d",&q)!=1)abort();if(limit&&q>limit)q=limit;std::vector<Query>x(q);for(auto&z:x)if(fscanf(f,"%d%d",&z.s,&z.t)!=2)abort();fclose(f);return x;}
struct Region{std::vector<int>b;std::vector<std::vector<u64>>d;};
struct Matrix{std::vector<int>rows,cols;std::vector<std::vector<int>>order;int block=1,blocks=0;};
struct Stats{uint64_t settled=0,regions=0,matrices=0,acts=0,finals=0,pushes=0,pops=0,inspect=0,cross=0,same=0;uint64_t buckets[5]{},work[5]{};double endpoint=0;};
class DDG{
 const Graph&g;int side,rn;std::vector<int>rid,bpos,bside;std::vector<Region>reg;std::vector<Matrix>mat;std::vector<std::vector<std::pair<int,int>>> rowm;std::vector<int> matrix_region;
 std::vector<u64> dist;std::vector<int> seen,done;int epoch=0;double prep_sssp_=0,prep_sort_=0;
 struct MI{struct X{u64 d;int c,r,b,p;bool operator>(const X&o)const{return std::tie(d,c,r,b,p)>std::tie(o.d,o.c,o.r,o.b,o.p);}};int ep=0;std::vector<int>active;std::priority_queue<X,std::vector<X>,std::greater<X>>h;uint64_t pushes=0,pops=0,inspect=0;};std::vector<MI> ms;
 using N=std::tuple<u64,int,int,int>; // distance, kind(0 node), id, generation
 std::priority_queue<N,std::vector<N>,std::greater<N>>pq;
 std::vector<int> touched_m,touched_r,mgen,mact;
 std::vector<u64> local(int s,int R){std::vector<u64>d(side*side,INF);int x0=(R%rn)*side,y0=(R/rn)*side;auto idx=[&](int v){return (v/g.n-y0)*side+(v%g.n-x0);};std::priority_queue<std::pair<u64,int>,std::vector<std::pair<u64,int>>,std::greater<std::pair<u64,int>>>q;d[idx(s)]=0;q.push({0,s});while(!q.empty()){auto[du,u]=q.top();q.pop();if(du!=d[idx(u)])continue;for(auto e:g.a[u])if(rid[e.v]==R){u64 nd=du+e.w;int z=idx(e.v);if(nd<d[z])d[z]=nd,q.push({nd,e.v});}}return d;}
 void mpush(int m,int r,int b,int p,u64 base,Stats&st){auto&M=mat[m];auto&S=ms[m];auto&o=M.order[r*M.blocks+b];while(p<(int)o.size()&&done[M.cols[o[p]]]==epoch)p++,S.inspect++;if(p==(int)o.size())return;int c=o[p];u64 z=base+reg[matrix_region[m]].d[bpos[M.rows[r]]][bpos[M.cols[c]]];S.h.push({z,c,r,b,p});S.pushes++;st.pushes++;}
 void activate(int m,int r,u64 base,Stats&st){auto&S=ms[m];auto&M=mat[m];if(S.ep!=epoch){S.ep=epoch;S.active.assign(M.rows.size(),0);S.h={};S.pushes=S.pops=S.inspect=0;touched_m.push_back(m);mact[m]=0;}if(S.active[r])return;S.active[r]=1;mact[m]++;st.acts++;for(int b=0;b<M.blocks;b++)mpush(m,r,b,0,base,st);emit(m,st);}
 void emit(int m,Stats&st){auto&S=ms[m];auto&M=mat[m];while(!S.h.empty()&&done[M.cols[S.h.top().c]]==epoch){auto x=S.h.top();S.h.pop();S.pops++;st.pops++;mpush(m,x.r,x.b,x.p+1,dist[M.rows[x.r]],st);}if(!S.h.empty()){mgen[m]++;pq.push({S.h.top().d,1,m,mgen[m]});}}
 void finish_stats(Stats&st){for(int m:touched_m){auto&M=mat[m];int pct=100*mact[m]/std::max(1,(int)M.rows.size());int b=pct<=10?0:pct<=25?1:pct<=50?2:pct<=75?3:4;st.buckets[b]++;st.work[b]+=ms[m].pushes+ms[m].pops+ms[m].inspect;st.inspect+=ms[m].inspect;}st.matrices+=touched_m.size();}
public:
 DDG(const Graph&G,int s):g(G),side(s),rn(G.n/s),rid(G.V),bpos(G.V,-1),bside(G.V,-1),dist(G.V),seen(G.V),done(G.V){int R=rn*rn;reg.resize(R);for(int v=0;v<g.V;v++)rid[v]=(v/g.n/side)*rn+(v%g.n/side);for(int R0=0;R0<R;R0++){int x0=(R0%rn)*side,y0=(R0/rn)*side;auto add=[&](int v,int sd){for(auto e:g.a[v])if(rid[e.v]!=R0){bpos[v]=reg[R0].b.size();bside[v]=sd;reg[R0].b.push_back(v);break;}};for(int x=x0;x<x0+side;x++)add(y0*g.n+x,0);for(int y=y0+1;y<y0+side;y++)add(y*g.n+x0+side-1,1);for(int x=x0+side-2;x>=x0;x--)add((y0+side-1)*g.n+x,2);for(int y=y0+side-2;y>y0;y--)add(y*g.n+x0,3);}
  for(int R0=0;R0<R;R0++){auto&rr=reg[R0];int B=rr.b.size();rr.d.assign(B,std::vector<u64>(B));for(int i=0;i<B;i++){auto ts=std::chrono::steady_clock::now();auto d=local(rr.b[i],R0);prep_sssp_+=std::chrono::duration<double>(std::chrono::steady_clock::now()-ts).count();int x0=(R0%rn)*side,y0=(R0/rn)*side;for(int j=0;j<B;j++){int v=rr.b[j],z=(v/g.n-y0)*side+(v%g.n-x0);rr.d[i][j]=d[z];}}std::vector<std::vector<int>> sides(4);for(int v:rr.b)sides[bside[v]].push_back(v);for(int a=0;a<4;a++)for(int bb=0;bb<4;bb++)if(a!=bb){Matrix M;M.rows=sides[a];M.cols=sides[bb];if(a>bb)std::reverse(M.rows.begin(),M.rows.end());else std::reverse(M.cols.begin(),M.cols.end());M.block=std::max(2,(int)std::sqrt(M.cols.size()));M.blocks=(M.cols.size()+M.block-1)/M.block;M.order.resize(M.rows.size()*M.blocks);for(int i=0;i<(int)M.rows.size();i++)for(int b=0;b<M.blocks;b++){auto&o=M.order[i*M.blocks+b];int lo=b*M.block,hi=std::min((int)M.cols.size(),lo+M.block);for(int c=lo;c<hi;c++)o.push_back(c);auto ts=std::chrono::steady_clock::now();std::sort(o.begin(),o.end(),[&](int x,int y){return std::tie(rr.d[bpos[M.rows[i]]][bpos[M.cols[x]]],x)<std::tie(rr.d[bpos[M.rows[i]]][bpos[M.cols[y]]],y);});prep_sort_+=std::chrono::duration<double>(std::chrono::steady_clock::now()-ts).count();}matrix_region.push_back(R0);mat.push_back(std::move(M));}}
  rowm.resize(g.V);for(int m=0;m<(int)mat.size();m++)for(int r=0;r<(int)mat[m].rows.size();r++)rowm[mat[m].rows[r]].push_back({m,r});ms.resize(mat.size());mgen.resize(mat.size());mact.resize(mat.size());
  // Mechanical coverage: each ordered off-diagonal pair occurs once, exactly.
  for(int R0=0;R0<R;R0++){int B=reg[R0].b.size();std::vector<int>cov(B*B);for(int m=0;m<(int)mat.size();m++)if(matrix_region[m]==R0)for(int u:mat[m].rows)for(int v:mat[m].cols){int i=bpos[u],j=bpos[v];if(reg[R0].d[i][j]>=INF||++cov[i*B+j]!=1)abort();}for(int i=0;i<B;i++)for(int j=0;j<B;j++)if(i!=j&&bside[reg[R0].b[i]]==bside[reg[R0].b[j]])++cov[i*B+j];for(int i=0;i<B;i++)for(int j=0;j<B;j++)if(i!=j&&cov[i*B+j]!=1)abort();}
 }
 double prep_sssp()const{return prep_sssp_;}double prep_sort()const{return prep_sort_;}int boundary_count()const{int z=0;for(auto&r:reg)z+=r.b.size();return z;}int matrix_count()const{return mat.size();}
 u64 explicit_query(int s,int t,Stats&st){epoch++;while(!pq.empty())pq.pop();int rs=rid[s],rt=rid[t];auto te=std::chrono::steady_clock::now();auto ds=local(s,rs),dt=local(t,rt);st.endpoint+=std::chrono::duration<double>(std::chrono::steady_clock::now()-te).count();u64 best=rs==rt?ds[(t/g.n-(rs/rn)*side)*side+(t%g.n-(rs%rn)*side)]:INF;auto set=[&](int v,u64 d){if(seen[v]!=epoch||d<dist[v])seen[v]=epoch,dist[v]=d,pq.push({d,0,v,0});};int x0=(rs%rn)*side,y0=(rs/rn)*side;for(int v:reg[rs].b)set(v,ds[(v/g.n-y0)*side+(v%g.n-x0)]);while(!pq.empty()){auto[d,k,u,z]=pq.top();pq.pop();if(k||seen[u]!=epoch||dist[u]!=d||done[u]==epoch)continue;if(d>=best)break;done[u]=epoch;st.settled++;if(rid[u]==rt){int xx=(rt%rn)*side,yy=(rt/rn)*side;best=std::min(best,d+dt[(u/g.n-yy)*side+(u%g.n-xx)]);}int R=rid[u],i=bpos[u];for(int j=0;j<(int)reg[R].b.size();j++)if(j!=i)set(reg[R].b[j],d+reg[R].d[i][j]);for(auto e:g.a[u])if(rid[e.v]!=R)set(e.v,d+e.w),st.cross++;}return best;}
 u64 implicit_query(int s,int t,Stats&st){epoch++;while(!pq.empty())pq.pop();touched_m.clear();int rs=rid[s],rt=rid[t];auto te=std::chrono::steady_clock::now();auto ds=local(s,rs),dt=local(t,rt);st.endpoint+=std::chrono::duration<double>(std::chrono::steady_clock::now()-te).count();u64 best=rs==rt?ds[(t/g.n-(rs/rn)*side)*side+(t%g.n-(rs%rn)*side)]:INF;auto set=[&](int v,u64 d){if(seen[v]!=epoch||d<dist[v])seen[v]=epoch,dist[v]=d,pq.push({d,0,v,0});};int x0=(rs%rn)*side,y0=(rs/rn)*side;for(int v:reg[rs].b)set(v,ds[(v/g.n-y0)*side+(v%g.n-x0)]);while(!pq.empty()){auto[d,k,u,z]=pq.top();pq.pop();if(k){if(z!=mgen[u])continue;auto&S=ms[u];emit(u,st);if(S.h.empty()||S.h.top().d!=d)continue;int v=mat[u].cols[S.h.top().c];set(v,d);continue;}if(seen[u]!=epoch||dist[u]!=d||done[u]==epoch)continue;if(d>=best)break;done[u]=epoch;st.settled++;st.finals++;if(rid[u]==rt){int xx=(rt%rn)*side,yy=(rt/rn)*side;best=std::min(best,d+dt[(u/g.n-yy)*side+(u%g.n-xx)]);}for(int v:reg[rid[u]].b)if(v!=u&&bside[v]==bside[u]){set(v,d+reg[rid[u]].d[bpos[u]][bpos[v]]);st.same++;}for(auto [m,r]:rowm[u])activate(m,r,d,st);for(auto e:g.a[u])if(rid[e.v]!=rid[u])set(e.v,d+e.w),st.cross++;}finish_stats(st);return best;}
};
int main(int ac,char**av){if(ac<4){fprintf(stderr,"usage: %s graph queries answers [side=16] [limit=0]\n",av[0]);return 2;}int side=ac>4?atoi(av[4]):16,lim=ac>5?atoi(av[5]):0;Graph g=load_graph(av[1]);auto q=load_queries(av[2],lim);FILE*f=fopen(av[3],"r");std::vector<u64>ref(q.size());for(auto&x:ref){unsigned long long z;if(fscanf(f,"%llu",&z)!=1)abort();x=z;}fclose(f);auto p0=std::chrono::steady_clock::now();DDG d(g,side);auto p1=std::chrono::steady_clock::now();Stats a,b;std::vector<u64>x(q.size()),y(q.size());auto t0=std::chrono::steady_clock::now();for(int i=0;i<(int)q.size();i++)x[i]=d.explicit_query(q[i].s,q[i].t,a);auto t1=std::chrono::steady_clock::now();for(int i=0;i<(int)q.size();i++)y[i]=d.implicit_query(q[i].s,q[i].t,b);auto t2=std::chrono::steady_clock::now();for(int i=0;i<(int)q.size();i++)if(x[i]!=ref[i]||y[i]!=ref[i]){fprintf(stderr,"wrong query %d ref=%llu dense=%llu implicit=%llu\n",i,(unsigned long long)ref[i],(unsigned long long)x[i],(unsigned long long)y[i]);return 3;}auto sec=[](auto a,auto b){return std::chrono::duration<double>(b-a).count();};printf("side=%d q=%zu boundary=%d matrices=%d preprocess=%.3f boundary_sssp=%.3f sorted_index=%.3f other_preprocess=%.3f dense=%.3f implicit=%.3f speedup=%.2fx exact=yes\n",side,q.size(),d.boundary_count(),d.matrix_count(),sec(p0,p1),d.prep_sssp(),d.prep_sort(),sec(p0,p1)-d.prep_sssp()-d.prep_sort(),sec(t0,t1),sec(t1,t2),sec(t0,t1)/sec(t1,t2));printf("dense_endpoint=%.3f dense_global=%.3f implicit_endpoint=%.3f implicit_global=%.3f\n",a.endpoint,sec(t0,t1)-a.endpoint,b.endpoint,sec(t1,t2)-b.endpoint);printf("implicit settled=%llu matrices=%llu activations=%llu finalizations=%llu pushes=%llu stale_pops=%llu inspections=%llu same_side_relax=%llu cross_relax=%llu\n",(unsigned long long)b.settled,(unsigned long long)b.matrices,(unsigned long long)b.acts,(unsigned long long)b.finals,(unsigned long long)b.pushes,(unsigned long long)b.pops,(unsigned long long)b.inspect,(unsigned long long)b.same,(unsigned long long)b.cross);for(int i=0;i<5;i++)printf("occupancy_bucket=%d matrices=%llu work=%llu\n",i,(unsigned long long)b.buckets[i],(unsigned long long)b.work[i]);rusage ru{};getrusage(RUSAGE_SELF,&ru);printf("peak_rss=%ldKiB\n",ru.ru_maxrss);}
